/**
 * Story 312 — the steps that go with a treadmill run inside a workout.
 *
 * The phone lives in a locker during a gym class, so nothing on it counts the
 * run: the 2026-08-26 class holds 289 steps in Health Connect against the
 * ~3,200 the 3.8 km block alone accounts for. This estimates the missing ones
 * from what the owner types, the same way `activity-burn.ts` estimates energy —
 * derived on read, never stored, always flagged, and skipped rather than faked
 * when the basis is missing.
 *
 * **The model is cadence, not steps per kilometre.** Measured on the owner's own
 * recorded run (2026-08-25, 6.5 km; see `docs/spikes/312-evidence/`), Health
 * Connect's per-minute step buckets give 24 points between 10.8 and 15.2 km/h,
 * and across them:
 *
 * - cadence is 158.7 spm, sd 1.04 — a 0.7% spread
 * - stride is 1.149 → 1.586 m/step — a 38% spread
 *
 * Legs turn over at a fixed rate and cover more ground per step when they go
 * faster, so **steps are a function of time, not of distance**:
 *
 *     steps ≈ moving_time_minutes × 159
 *
 * That is algebraically the same as a speed-dependent `steps/km = 9540 / kmh`,
 * with the speed term cancelled instead of fitted — and it means a mistyped
 * distance cannot corrupt the step count. Distance keeps one job: deciding
 * whether the cadence model applies at all.
 *
 * What this module deliberately does NOT do:
 *
 * - **No fallback when the moving time is absent.** An estimate with no
 *   duration is a guess about how long someone ran, and the honest output is
 *   nothing (story AC 2). The activity and its distance still publish.
 * - **No walking estimate.** The trustworthy walking sessions on this phone
 *   average 54–64 spm across a session, which is a stroll with standing in it,
 *   not a deliberate walking cadence. Below [RUNNING_MIN_KMH] there is no
 *   calibration and so no number.
 */

/** Steps per minute while running: 158.7 measured, sd 1.04, rounded. */
export const RUNNING_CADENCE_SPM = 159;

/**
 * Below this the gait is a walk, where the cadence above does not hold and
 * nothing on this phone calibrates a replacement. Returns no estimate.
 */
export const RUNNING_MIN_KMH = 7;

/** The speeds the cadence was actually measured across (2026-08-25 run). */
export const CALIBRATED_MIN_KMH = 10.8;
export const CALIBRATED_MAX_KMH = 15.2;

/**
 * Faster than any human sustains over a treadmill block, so this is a typo —
 * 38 km in the distance field, or 3 minutes in the moving time. Refusing beats
 * publishing tens of thousands of invented steps into the shared health record.
 */
export const IMPLAUSIBLE_KMH = 25;

export interface ActivityStepsSignal {
    /** Same-activity distance in metres, from `cardio_details`. */
    distance_m?: number | null;
    /** How long that distance took, in minutes — the estimate's whole basis. */
    moving_time_minutes?: number | null;
}

export interface ActivityStepsEstimate {
    steps: number;
    /**
     * Always true. This module produces nothing but estimates — the field
     * exists so callers read the same shape as `ActivityBurn`, where a stored
     * value can arrive alongside an estimated one.
     */
    estimated: true;
    /** The pace the estimate was validated against, km/h. */
    speedKmh: number;
    /**
     * True when the pace sits outside the range the cadence was measured
     * across. The estimate is still the best available — cadence is flat, so
     * extending a constant is mild — but a 3.8 km block in a 14-minute moving
     * time is 16 km/h, past anything recorded here, and saying so is cheap.
     */
    extrapolated: boolean;
}

/**
 * The estimated steps for one activity, or `null` when there is no honest basis
 * for one: no moving time, no distance to check the pace against, a pace slower
 * than running, or a pace fast enough to be a typo.
 */
export function estimateActivitySteps(activity: ActivityStepsSignal): ActivityStepsEstimate | null {
    const minutes = activity.moving_time_minutes;
    const distanceM = activity.distance_m;
    if (minutes == null || minutes <= 0) return null;
    // Distance is not a multiplier here, but without it there is no way to tell
    // a treadmill run from twenty minutes of stretching.
    if (distanceM == null || distanceM <= 0) return null;

    const speedKmh = distanceM / 1000 / (minutes / 60);
    if (speedKmh < RUNNING_MIN_KMH || speedKmh > IMPLAUSIBLE_KMH) return null;

    return {
        steps: Math.round(minutes * RUNNING_CADENCE_SPM),
        estimated: true,
        speedKmh,
        extrapolated: speedKmh < CALIBRATED_MIN_KMH || speedKmh > CALIBRATED_MAX_KMH,
    };
}
