import type { Activity, ActivitySource, ActivityType, ActivityWithDistance, NewActivity } from '@motivation/shared';
import { estimateActivitySteps, isSynthesizedCalendarEvent, isUserOwnedActivity } from '@motivation/shared';
import { getAppTimeZone, appTodayPlainDate } from './app-timezone.service.js';
import { HealthService } from './health.service.js';
import { createComponentLogger } from '../utils/component-logger.js';

// Ships to the server client-log stream — `npm run logs -w server -- --module=hc-sync`.
const log = createComponentLogger('hc-sync');

/**
 * Health Connect bridge sync (story 250, replacing the dead Strava API).
 *
 * The sideloaded bridge app (hc-bridge/) serves Health Connect data on
 * loopback; the PWA fetches it directly — localhost is potentially-trustworthy
 * so there is no mixed-content block and the service worker passes the request
 * through untouched (spike 249). Mapped activities are pushed through the
 * normal health API (POST /activities + PATCH /cardio-details), so dedup rides
 * the existing unique `external_id` index and offline behavior matches manual
 * entry.
 */

// Story 257: resolved in config.ts (MOTIVATION_HC_BRIDGE_HOST/PORT) so
// instance builds can point the bridge at the mock stub; re-exported here
// because this module owns the bridge API surface.
import { HC_BRIDGE_URL } from '../config.js';
export { HC_BRIDGE_URL };

/**
 * The bridge returns 429 `{reason:"rate_limited"}` when Health Connect throttles
 * reads (its per-app read quota). Distinct from a generic failure so the Status
 * screen can show a cooldown + retry instead of an opaque error.
 */
export class HcRateLimitError extends Error {
    readonly reason = 'rate_limited';
    constructor(message = 'Health Connect is rate-limiting reads') {
        super(message);
        this.name = 'HcRateLimitError';
    }
}

/**
 * The bridge is not answering on loopback, i.e. its foreground service is not running and waking it
 * did not help. Distinct from a generic failure because the raw symptom is
 * `TypeError: Failed to fetch`, which tells the user nothing (story 301).
 */
export class HcBridgeUnreachableError extends Error {
    readonly reason = 'bridge_unreachable';
    constructor(message = 'The Health Connect bridge app is not responding on this device') {
        super(message);
        this.name = 'HcBridgeUnreachableError';
    }
}

/**
 * Chrome intent URL that launches (or foregrounds) the bridge app, which
 * starts its foreground service — the PWA-side half of story 250 decision 6.
 *
 * Since story 297 the bridge stops itself after 10 minutes idle, so this is no longer just a manual
 * "Open bridge app" affordance: {@link HealthConnectService.ensureBridgeAwake} navigates here
 * automatically before a sync. It lands in the bridge's `WakeActivity`, which is translucent and
 * finishes immediately, so Chrome comes straight back to the front.
 */
export const HC_BRIDGE_LAUNCH_URL = 'intent://sync#Intent;scheme=hcbridge;package=dev.motivation.hcreader;end';

/**
 * Waking the bridge, behind one indirection so tests can assert a wake was attempted without jsdom
 * trying to navigate, and can shrink the poll instead of waiting eight real seconds.
 *
 * `trigger` assigns `location.href` rather than unloading the page — that is what hands off to
 * Android while keeping the PWA alive, so the sync can carry on once the bridge answers.
 *
 * `timeoutMs` covers a cold app start plus the Health Connect permission check, which measured well
 * under a second on the Pixel; 8 s is generous headroom.
 */
export const bridgeWake = {
    timeoutMs: 8_000,
    pollIntervalMs: 500,
    trigger(): void {
        window.location.href = HC_BRIDGE_LAUNCH_URL;
    },
};

/** One exercise session as served by the bridge's GET /activities. */
export interface BridgeActivity {
    id: string;
    source: string;
    exerciseType: number;
    start: string;
    end: string;
    durationSec: number;
    distanceMeters: number;
    /** Same-source active energy for the session window (story 259); null when the writer recorded none. */
    energyKcal: number | null;
}

export interface BridgeActivitiesResponse {
    generatedAt: string;
    rangeDays: number;
    activityCount: number;
    activities: BridgeActivity[];
}

/** One per-local-day step total as served by the bridge's GET /steps/daily (story 251). */
export interface BridgeDailySteps {
    date: string;
    steps: number;
}

export interface BridgeDailyStepsResponse {
    generatedAt: string;
    rangeDays: number;
    days: BridgeDailySteps[];
}

/** `daily_steps.source` value for bridge-ingested rows — HC aggregates across writers, so the writer package is not preserved. */
export const HC_STEPS_SOURCE = 'health_connect';

export type BridgeMapResult =
    | { kind: 'mapped'; activity: NewActivity; distanceMeters: number }
    | {
          kind: 'skipped';
          /**
           * `unknown_source` means a writer we have never seen — always a warning, because it is
           * how a Health Connect writer change announces itself (story 298: Google Health arriving
           * cost 94 dropped activities a day before anyone noticed).
           *
           * `ignored_source` is the deliberate opposite: a writer we know about and have decided
           * not to ingest ({@link IGNORED_SOURCES}). Keeping the two apart is what stops 84
           * expected skips per sync from reading like a fault (story 303).
           */
          reason: 'unknown_type' | 'unknown_source' | 'ignored_source';
      };

export interface HcSyncSummary {
    created: number;
    skippedExisting: number;
    skippedUnknownType: number;
    /**
     * Sessions from a Health Connect writer in neither `SOURCE_MAP` nor {@link IGNORED_SOURCES}.
     * Non-zero means a writer changed under us and activities are being dropped — it is logged as
     * a warning naming the package, never counted silently (story 298).
     */
    skippedUnknownSource: number;
    /** Sessions from a writer in {@link IGNORED_SOURCES} — expected, and counted rather than discarded (story 303). */
    skippedIgnoredSource: number;
    /** Which ignored packages this payload actually contained, so the log and the UI can name them. */
    ignoredSources: string[];
    /**
     * No mapped writer produced a single session while an ignored one did (story 303).
     *
     * This is the one failure mode of trusting a single writer: Google Health is midway through
     * migrating Google Fit's records and has already blanked a whole local day once. If it resumes
     * and finishes, ingest would quietly go to zero. An empty payload does not set this — no
     * sessions at all is a quiet day, not a takeover.
     */
    mappedWriterSilent: boolean;
    /**
     * Sessions not created because an activity with the same type and start instant already
     * existed, whoever wrote it (story 300). Non-zero is normal during the Google Fit → Google
     * Health migration; it is the count of duplicates prevented.
     */
    skippedDuplicateStart: number;
    /**
     * Existing rows replaced in place by a better version of the same session — a longer or
     * further recording superseding a partial one. Counted separately from a plain skip so
     * re-syncs that change stored data are visible rather than silent.
     */
    duplicatesUpgraded: number;
    /** Days whose step total was new or changed (story 251); unchanged days are not re-written. */
    stepDaysUpserted: number;
    /**
     * The write-back leg (story 299): sessions published into Health Connect, records removed
     * there because the activity was deleted or edited out of eligibility, and the count published
     * at the fallback slot for want of a recorded start time.
     *
     * `pushed` is the size of the whole desired set, not a delta — the push is a reconcile, so it
     * re-states every eligible activity every sync and lets Health Connect's `clientRecordId`
     * dedup it. A steady number here is the healthy case, not churn.
     */
    pushedToHealthConnect: number;
    pushedWithoutStart: number;
    pushRemovedFromHealthConnect: number;
    /** Eligible rows that could not be expressed as a session at all (no duration). */
    pushSkippedNoDuration: number;
    /**
     * The step estimate leg (story 312): how many sessions carried one, and how many steps that
     * came to in total.
     */
    pushedStepRecords: number;
    pushedStepsTotal: number;
    /**
     * Rows with a distance but no estimate — a blank moving time, almost always. Reported the way
     * {@link HcSyncSummary.pushedWithoutStart} is, because a silent gap here looks identical to a
     * session that genuinely had no running in it. The session and its distance still published.
     */
    pushDistanceWithoutSteps: number;
    /** Estimates whose pace sits outside the range the cadence was measured across. */
    pushStepsExtrapolated: number;
    /** Existing HC rows without a burn value that this sync PATCHed with bridge energy (story 259). */
    energyBackfilled: number;
    /**
     * Newly-created activities that share an exact start with a pre-existing one
     * of the same source+type (a different HC record id — typically a partial
     * session HC later superseded, so it reads as a duplicate). Surfaced to the
     * user with a "delete the older one?" prompt rather than silently dropped.
     */
    collisions: HcSyncCollision[];
}

/** One same-start pair flagged by a sync (see {@link HcSyncSummary.collisions}). */
export interface HcSyncCollision {
    type: string;
    source: ActivitySource;
    /** Shared start instant (ISO); both rows begin here. */
    start: string;
    newId: string;
    newExternalId: string;
    newDurationMinutes: number;
    existingId: string;
    existingExternalId: string | null;
    existingDurationMinutes: number;
}

/**
 * HC `ExerciseSessionRecord.exerciseType` → `activities.type`. Numbers verified against the
 * `androidx.health.connect:connect-client` 1.1.0 constants the bridge compiles against, not the
 * docs (story 303) — the two entries that were never checked were both wrong.
 *
 * Deliberately absent: **36** (`HIGH_INTENSITY_INTERVAL_TRAINING`, once mislabelled here as an
 * unexplained hand-added test type) and **81** (`WEIGHTLIFTING`, once mislabelled as Strava's
 * "other" — that is `0`, `OTHER_WORKOUT`). This app has a `hiit` and a `weight_training` type, so
 * both *could* map; they do not because the only sessions ever seen carrying them were hand-added
 * to Google Fit for gym work already logged here by hand, and ingesting those double-counts. That
 * has happened once already: 2026-08-07 carries a phantom `Run` beside the owner's manual `Gym`.
 * The unmapped-type warning names the number, so a writer that starts recording them for real
 * announces itself.
 *
 * **81 stays unmapped now that Strava is ingested, and the reason changes.** Strava wrote only two
 * types — 56 (12 sessions) and 81 (4) — and its 81s are genuine recorded strength sessions, not
 * hand-added stubs. They are still not ingested, because the owner logs gym work here by hand, so
 * taking them would double-count exactly as Fit's do. The visible cost is that those four now land
 * as `skippedUnknownType` rather than `ignored_source`: the type warning will name 81 whenever
 * Strava records strength again. That is noise we accept, not a signal to act on.
 */
const EXERCISE_TYPE_MAP: Record<number, ActivityType> = {
    56: 'running', // RUNNING
    57: 'running', // RUNNING_TREADMILL
    79: 'walking', // WALKING
    8: 'cycling', // BIKING
};

const TITLE_BY_TYPE: Partial<Record<ActivityType, string>> = {
    running: 'Run',
    walking: 'Walk',
    cycling: 'Ride',
};

/**
 * The other direction (story 299): `activities.type` → HC `exerciseType`, for the sessions this
 * app publishes back into Health Connect.
 *
 * Every number here was read out of `androidx.health.connect:connect-client` 1.1.0 with `javap`,
 * the same jar the bridge compiles against — never from the documentation. Story 303 checked two
 * documented constants and found both wrong, which is a good enough reason to never trust the docs
 * for this table again.
 *
 * This is **not** the inverse of {@link EXERCISE_TYPE_MAP} and must not be derived from it. That
 * map is deliberately partial — it leaves 36 and 81 unmapped so hand-added Google Fit stubs do not
 * double-count the owner's manual gym logging. Those two are precisely the types the owner logs
 * *most* by hand (8 `hiit` + 6 `weight_training` of 22 manual activities measured on 2026-08-25),
 * so a write-back built from the read map would publish almost nothing. Read and write disagree
 * because they answer different questions: "should I ingest this?" and "how do I say this?".
 */
export const HC_EXERCISE_TYPE_BY_ACTIVITY_TYPE: Record<ActivityType, number> = {
    running: 56, // RUNNING
    cycling: 8, // BIKING
    walking: 79, // WALKING
    hiking: 37, // HIKING
    swimming: 74, // SWIMMING_POOL — the likelier of the two; 73 is open water
    tennis: 76, // TENNIS
    ice_skate: 39, // ICE_SKATING
    alpine_ski: 61, // SKIING
    hiit: 36, // HIGH_INTENSITY_INTERVAL_TRAINING
    weight_training: 81, // WEIGHTLIFTING
    workout: 0, // OTHER_WORKOUT
};

/**
 * `activities.type` is typed as `string` (see the shared type's note), so an unmapped value is
 * reachable. It becomes `OTHER_WORKOUT` rather than being dropped — the story's design note: a
 * session recorded under a vaguer type is still the training the user did, whereas a dropped one
 * is the bug this whole story exists to fix.
 */
export function hcExerciseTypeFor(type: string): number {
    return HC_EXERCISE_TYPE_BY_ACTIVITY_TYPE[type as ActivityType] ?? HC_EXERCISE_TYPE_BY_ACTIVITY_TYPE.workout;
}

/**
 * The Health Connect writers this app ingests (story 303, widened again after re-measuring).
 *
 * Google Fit: measured on 2026-08-25 over a 30-day window, 97 sessions carrying 165 km, and the
 * sole writer for the four most recent local days.
 *
 * Strava was ignored here between 303 and this change, on the stated grounds that "Google Fit
 * records the same runs". Re-measured against the whole `activities` table over Strava's active
 * window (2026-07-04 → 2026-08-19), that was false: **Strava recorded 17 runs, Fit 6** — and five
 * of Fit's six are the cross-writer pairs the duplicate fix already matched. Fit's one independent
 * row is a 5 min / 796 m fragment of the run Strava logged as 20 min / 3720 m. The "within 4%"
 * figure came from the only two runs that comparison ever sampled. Fit caught nothing Strava
 * missed, and missed twelve Strava had.
 *
 * Re-mapping is cheap while Strava is silent (it has written nothing since 2026-08-19) and is the
 * only thing that makes a revival land: {@link HcSyncSummary.mappedWriterSilent} cannot fire for a
 * writer resuming *alongside* a healthy Fit, so an ignored Strava would be dropped indefinitely.
 * Overlap is safe — `sameActivityKey` is source-blind and `isBetter` prefers distance, so a run
 * both wrote resolves to one row, the fuller one (Strava in both pairs measured).
 */
const SOURCE_MAP: Record<string, ActivitySource> = {
    'com.google.android.apps.fitness': 'health_connect_android_fitness',
    'com.strava': 'health_connect_strava',
};

/**
 * Writers we know about and deliberately do not ingest, with the reason (story 303).
 *
 * This is not the same thing as an unrecognised package, and the difference is the point: a
 * writer listed here going *active* is news the owner needs — it is reported by name in the sync
 * summary — whereas an unlisted one is an alarm.
 *
 * Note what an entry here does **not** buy you: the "went active" signal only reaches the owner
 * through `mappedWriterSilent`, which requires *every* mapped writer to produce nothing. Fit writes
 * walking sessions almost daily, so a writer that resumes beside it is counted and `log.debug`'d
 * and nothing more. That is tolerable for Google Health, whose sessions are copies; it was not
 * tolerable for Strava, which is why Strava is mapped above rather than listed here.
 */
const IGNORED_SOURCES: Record<string, string> = {
    // 84 of 84 sessions matched a Google Fit session by start instant to the millisecond — 79 at
    // exactly +6 h (Amsterdam minus New York), 5 at the same instant — with distance stripped on
    // 83 of them. It contributes no activity Fit does not already have, more accurately.
    'com.fitbit.FitbitMobile': 'Google Health — every session measured was a copy of a Google Fit session',
};

function mapExerciseType(exerciseType: number): ActivityType | null {
    return EXERCISE_TYPE_MAP[exerciseType] ?? null;
}

/** Projects the session's start instant into the app timezone's local date. */
function localDateOf(startIso: string, timeZone: string): string {
    return Temporal.Instant.from(startIso).toZonedDateTimeISO(timeZone).toPlainDate().toString();
}

/** The `start` instant an HC activity was ingested with, from its metadata blob (null if absent/unparseable). */
function activityStartInstant(metadata: string | null | undefined): string | null {
    if (!metadata) return null;
    try {
        const parsed = JSON.parse(metadata) as { start?: unknown };
        return typeof parsed.start === 'string' ? parsed.start : null;
    } catch {
        return null;
    }
}

/**
 * Same type at the same start instant = the same real activity, whoever wrote it (story 300).
 *
 * The source is deliberately **not** in this key. It used to be, and that made dedup structurally
 * blind to the duplicate that matters most: Google Health is migrating Google Fit's history by
 * *deleting* Fit's Health Connect records and rewriting them under its own package with fresh
 * UUIDs. Both `external_id` (a per-device HC record id) and a source-scoped key therefore see a
 * brand-new activity, and the same walk lands twice. Measured on 2026-08-22: 13 duplicate pairs,
 * every one sharing its start instant to the second.
 */
function sameActivityKey(type: string, start: string): string {
    return `${type}|${start}`;
}

export function mapBridgeActivity(bridge: BridgeActivity, timeZone: string): BridgeMapResult {
    const source = SOURCE_MAP[bridge.source];
    // The writer is decided before the exercise type on purpose: an ignored writer's session must
    // not also inflate the unmapped-type warning with a number nobody needs to act on.
    if (!source) {
        return { kind: 'skipped', reason: IGNORED_SOURCES[bridge.source] ? 'ignored_source' : 'unknown_source' };
    }

    const type = mapExerciseType(bridge.exerciseType);
    if (!type) return { kind: 'skipped', reason: 'unknown_type' };

    const date = localDateOf(bridge.start, timeZone);

    return {
        kind: 'mapped',
        distanceMeters: bridge.distanceMeters,
        activity: {
            type,
            source,
            title: TITLE_BY_TYPE[type] ?? type,
            date,
            duration_minutes: Math.round(bridge.durationSec / 60),
            // Real energy from the watch (story 259); undefined keeps the row
            // on the MET-estimate fallback (story 258).
            calories_burned: bridge.energyKcal ?? undefined,
            external_id: `hc_${bridge.id}`,
            metadata: JSON.stringify({
                start: bridge.start,
                end: bridge.end,
                hc_exercise_type: bridge.exerciseType,
            }),
        },
    };
}

// --- Write-back: Motivation → Health Connect (story 299) ---

/** One session as `POST /activities` wants it. Mirrors `BridgeServer.PendingWrite`. */
export interface BridgeWriteActivity {
    /** The activity's own UUID — becomes HC's `clientRecordId`, so a re-push replaces rather than adds. */
    clientId: string;
    /** `updated_at` as epoch seconds — HC's `clientRecordVersion`, so an edit supersedes what is stored. */
    version: number;
    exerciseType: number;
    title: string;
    start: string;
    end: string;
    /** UTC offset in force at `start`, so other apps render the session at the local time it happened. */
    startZoneOffset: string;
    endZoneOffset: string;
    distanceMeters?: number;
    /**
     * The estimated steps for the run inside this session (story 312), absent when
     * {@link estimateActivitySteps} had no honest basis for one. Absent is not zero: zero would
     * publish "this session had no steps", a claim we do not have.
     */
    stepCount?: number;
}

export interface BridgeWriteResponse {
    sessionsWritten: number;
    distancesWritten: number;
    stepsWritten: number;
    stepsTotal: number;
    sessionsDeleted: number;
    distancesDeleted: number;
    stepsDeleted: number;
    distanceWithoutSteps: number;
}

/**
 * The bridge refused the payload (400) or has no write grant (403). Both are permanent until
 * something changes — retrying the same sync cannot fix either — so they are their own error
 * rather than a generic failure the user is invited to retry into.
 */
export class HcWriteRejectedError extends Error {
    constructor(readonly reason: string, message: string) {
        super(message);
        this.name = 'HcWriteRejectedError';
    }
}

/**
 * The owner's own rows are published (story 299 AC: "decide which activities are eligible"), which
 * since story 323 means `manual` **and adopted `calendar`** — a TRIB3 class the owner tapped to log
 * is theirs, and belongs in Health Connect exactly as a hand-logged one does.
 *
 * Ingested rows are still excluded: Google Fit and Strava write their own Health Connect records,
 * so pushing those back would duplicate an existing record under a second writer's name.
 *
 * The `!isSynthesizedCalendarEvent` half is load-bearing and not defensive. `existing` in
 * {@link HealthConnectSyncService.pushActivities} comes from the *server's* `GET /activities`,
 * which appends live projections of matched calendar events — so without this, every booked class
 * in the window would publish as a completed session (including one booked for later today), and
 * `BridgeWriteActivity.clientId` would claim a `clientRecordId` for a row that does not exist.
 */
export function isEligibleForHealthConnect(activity: Activity): boolean {
    return isUserOwnedActivity(activity) && !isSynthesizedCalendarEvent(activity);
}

/** The local time of day a session with no recorded start is placed at — see {@link buildHealthConnectWrites}. */
export const HC_FALLBACK_LOCAL_START = '12:00:00';

export interface HealthConnectWritePlan {
    writes: BridgeWriteActivity[];
    /** Eligible rows with no usable duration — a session with no length cannot be expressed at all. */
    skippedNoDuration: number;
    /** Rows published at the fallback slot because they carry no start instant. */
    placedWithoutStart: number;
    /**
     * Rows carrying a distance whose steps could not be estimated — almost always a blank moving
     * time (story 312). Reported rather than swallowed, the way `placedWithoutStart` is: the
     * session and its distance still publish, and the fix is one number in the cardio form.
     */
    distanceWithoutSteps: number;
    /** Rows whose estimate sits outside the pace range the cadence was measured across. */
    stepsExtrapolated: number;
}

/** `updated_at` ("2026-08-24 21:13:25", UTC, second resolution) as epoch seconds. */
function versionOf(updatedAt: string | undefined): number {
    if (!updatedAt) return 0;
    const normalized = updatedAt.includes('T') ? updatedAt : `${updatedAt.replace(' ', 'T')}Z`;
    const ms = Date.parse(normalized);
    return Number.isFinite(ms) ? Math.floor(ms / 1000) : 0;
}

function zoneOffsetAt(instantIso: string, timeZone: string): string {
    return Temporal.Instant.from(instantIso).toZonedDateTimeISO(timeZone).offset;
}

/**
 * Turns the activities Motivation owns into the exact set Health Connect should hold for them.
 *
 * **Start times.** Manual activities carry only a date and a duration; story 299 added an optional
 * start time (`metadata.start`) for exactly this, because Health Connect records an *interval*, not
 * a day. Rows that have one are written at the instant the owner stated, untouched.
 *
 * Rows that do not — every activity logged before this shipped — are placed at
 * {@link HC_FALLBACK_LOCAL_START} local time on their own date. That is a stated convention, not a
 * measurement: `created_at` was tested as a proxy first and rejected on the data, because the same
 * weekly class was logged at 17:27Z, 18:53Z, 20:34Z, 22:25Z and 00:13Z the next day — a spread of
 * seven hours that would look authoritative while being wronger than a constant. The alternative,
 * publishing nothing for them, loses the history this story exists to surface, and the owner can
 * correct any one of them by typing a start. The count is reported, never silent.
 *
 * **A synthesized start never displaces a real one.** Two undated activities on one date would
 * otherwise both begin at exactly the fallback time, so a fallback session is walked forward past
 * whatever already occupies its slot.
 *
 * Nothing downstream would catch a pile-up: measured on-device on 2026-08-26, Health Connect does
 * **not** reject overlapping exercise sessions from a single writer — it accepted two of ours over
 * the same half hour without complaint. So this is not insurance against an insert failure, it is
 * the only thing standing between the fallback convention and a stack of sessions rendering on top
 * of each other in Google Health, double-counting their exercise minutes. Only fallback sessions
 * move: a start the owner typed is data, and data that collides is theirs to resolve.
 */
export function buildHealthConnectWrites(
    activities: ActivityWithDistance[],
    timeZone: string,
): HealthConnectWritePlan {
    const plan: HealthConnectWritePlan = {
        writes: [], skippedNoDuration: 0, placedWithoutStart: 0, distanceWithoutSteps: 0, stepsExtrapolated: 0,
    };

    const eligible = activities.filter(isEligibleForHealthConnect);
    const withDuration = eligible.filter((a) => {
        if ((a.duration_minutes ?? 0) > 0) return true;
        plan.skippedNoDuration++;
        return false;
    });

    // Deterministic order: the placement below depends on it, and a sync that shuffled its own
    // fallback slots would rewrite the same records with different times every run.
    const ordered = [...withDuration].sort((a, b) => (a.date === b.date ? a.id.localeCompare(b.id) : a.date.localeCompare(b.date)));

    const occupied: Array<{ from: number; to: number }> = [];
    const stated = new Map<string, string>();
    for (const a of ordered) {
        const start = activityStartInstant(a.metadata);
        if (!start) continue;
        stated.set(a.id, start);
        const from = Temporal.Instant.from(start).epochMilliseconds;
        occupied.push({ from, to: from + (a.duration_minutes ?? 0) * 60_000 });
    }

    for (const a of ordered) {
        const durationMs = (a.duration_minutes ?? 0) * 60_000;
        const statedStart = stated.get(a.id);
        let startInstant: Temporal.Instant;

        if (statedStart) {
            startInstant = Temporal.Instant.from(statedStart);
        } else {
            plan.placedWithoutStart++;
            let from = Temporal.PlainDateTime.from(`${a.date}T${HC_FALLBACK_LOCAL_START}`)
                .toZonedDateTime(timeZone)
                .toInstant().epochMilliseconds;
            // Each clash moves `from` strictly forward (to the end of the record it hit), so this
            // settles rather than circles.
            for (;;) {
                const clash = occupied.find((o) => from < o.to && from + durationMs > o.from);
                if (!clash) break;
                from = clash.to;
            }
            occupied.push({ from, to: from + durationMs });
            startInstant = Temporal.Instant.fromEpochMilliseconds(from);
        }

        const start = startInstant.toString();
        const end = startInstant.add({ milliseconds: durationMs }).toString();
        const hasDistance = !!(a.distance_m && a.distance_m > 0);

        // The step estimate (story 312). This publishes a *derived* figure, which story 299
        // refused to do for energy — and the two cases are not alike. `calories_burned` would have
        // sat beside the watch's real measurement with nothing to tell them apart; these steps fill
        // an interval where no writer on the phone has the run at all (289 counted across the
        // 50-minute class of 2026-08-26, against ~3,200 for the run). Health Connect resolves its
        // source priority per interval and this app is last in that list, so anything a real writer
        // recorded still wins and ours is credited only in the gaps.
        const steps = estimateActivitySteps({ distance_m: a.distance_m, moving_time_minutes: a.moving_time_minutes });
        if (steps) {
            if (steps.extrapolated) plan.stepsExtrapolated++;
        } else if (hasDistance) {
            plan.distanceWithoutSteps++;
        }

        plan.writes.push({
            clientId: a.id,
            version: versionOf(a.updated_at),
            exerciseType: hcExerciseTypeFor(a.type),
            title: a.title,
            start,
            end,
            startZoneOffset: zoneOffsetAt(start, timeZone),
            endZoneOffset: zoneOffsetAt(end, timeZone),
            // Distance is published where Motivation has it (16 of the 22 manual rows measured on
            // 2026-08-25 do). Energy stays deliberately absent — see the note above for why steps
            // are not the same call.
            ...(hasDistance ? { distanceMeters: a.distance_m as number } : {}),
            ...(steps ? { stepCount: steps.steps } : {}),
        });
    }

    return plan;
}

export class HealthConnectService {
    /** Cheap reachability probe for the Status screen dot. */
    static async pingBridge(): Promise<boolean> {
        try {
            const response = await fetch(`${HC_BRIDGE_URL}/ping`, { signal: AbortSignal.timeout(3_000) });
            return response.ok;
        } catch {
            return false;
        }
    }

    /**
     * Make sure the bridge is up before a sync, waking it if not (story 301).
     *
     * The bridge stops itself after 10 minutes idle (story 297), so an unprepared sync just threw
     * `TypeError: Failed to fetch` and left the user to go open the app by hand — which is exactly
     * what happened in the field the day v1.3 shipped. Ping first so the warm path costs nothing,
     * and only navigate to the wake link when it is actually needed.
     */
    static async ensureBridgeAwake(): Promise<boolean> {
        if (await this.pingBridge()) return true;

        log.info('hc-sync: bridge asleep — waking it via the deep link');
        try {
            bridgeWake.trigger();
        } catch (err) {
            log.warn('hc-sync: could not trigger the bridge wake', err);
            return false;
        }

        const attempts = Math.max(1, Math.ceil(bridgeWake.timeoutMs / bridgeWake.pollIntervalMs));
        for (let attempt = 1; attempt <= attempts; attempt++) {
            await new Promise((resolve) => setTimeout(resolve, bridgeWake.pollIntervalMs));
            if (await this.pingBridge()) {
                log.info('hc-sync: bridge woke', { afterMs: attempt * bridgeWake.pollIntervalMs });
                return true;
            }
        }
        log.warn('hc-sync: bridge did not answer after waking', { waitedMs: bridgeWake.timeoutMs });
        return false;
    }

    static async fetchBridgeActivities(): Promise<BridgeActivitiesResponse> {
        const response = await fetch(`${HC_BRIDGE_URL}/activities`);
        if (response.status === 429) throw new HcRateLimitError();
        if (!response.ok) {
            throw new Error(`Bridge /activities failed: ${response.status}`);
        }
        return response.json();
    }

    static async fetchBridgeDailySteps(): Promise<BridgeDailyStepsResponse> {
        const response = await fetch(`${HC_BRIDGE_URL}/steps/daily`);
        if (response.status === 429) throw new HcRateLimitError();
        if (!response.ok) {
            throw new Error(`Bridge /steps/daily failed: ${response.status}`);
        }
        return response.json();
    }

    /**
     * Full activity sync: bridge → map → dedup against the server window →
     * POST each new activity (+ PATCH distance). Errors are not swallowed —
     * a failing push aborts the sync and surfaces raw (fail loud).
     */
    static async sync(): Promise<HcSyncSummary> {
        try {
            const summary = await this.runSync();
            log.info('hc-sync: completed', summary);
            return summary;
        } catch (err) {
            log.error('hc-sync: failed', err);
            throw err;
        }
    }

    private static async runSync(): Promise<HcSyncSummary> {
        log.info('hc-sync: started');
        // Story 301: the bridge sleeps when idle, so wake it before reading rather than letting the
        // first fetch fail with an opaque TypeError.
        if (!(await this.ensureBridgeAwake())) throw new HcBridgeUnreachableError();
        const bridge = await this.fetchBridgeActivities();
        log.debug('hc-sync: bridge activities', {
            total: bridge.activities.length,
            rangeDays: bridge.rangeDays,
        });

        const today = appTodayPlainDate();
        const from = today.subtract({ days: bridge.rangeDays + 1 }).toString();
        const existing = await HealthService.getActivitiesByDateRange(from, today.toString());
        const existingByExternalId = new Map(
            existing.filter((a) => a.external_id).map((a) => [a.external_id!, a]),
        );

        const timeZone = getAppTimeZone();
        const summary: HcSyncSummary = {
            created: 0,
            skippedExisting: 0,
            skippedUnknownType: 0,
            skippedUnknownSource: 0,
            skippedIgnoredSource: 0,
            ignoredSources: [],
            mappedWriterSilent: false,
            skippedDuplicateStart: 0,
            duplicatesUpgraded: 0,
            stepDaysUpserted: 0,
            energyBackfilled: 0,
            pushedToHealthConnect: 0,
            pushedWithoutStart: 0,
            pushRemovedFromHealthConnect: 0,
            pushSkippedNoDuration: 0,
            pushedStepRecords: 0,
            pushedStepsTotal: 0,
            pushDistanceWithoutSteps: 0,
            pushStepsExtrapolated: 0,
            collisions: [],
        };

        // Index every activity we know about by (type, exact start) — one entry per real session,
        // whoever wrote it (story 300). Seeded with the pre-sync rows and extended as we create, so
        // "synced last time", "both writers in this payload" and "a fuller version arrived later"
        // all resolve to the same slot instead of becoming extra rows.
        // Story 298: collected so an unrecognised writer or exercise type is reported by name
        // instead of only inflating a counter. A writer change is exactly how activity ingest
        // breaks, and it broke silently once already.
        const unknownSources = new Set<string>();
        const unknownTypes = new Set<number>();
        // Story 303: counted off the raw payload rather than the mapping result, because the
        // question the alarm asks is "did the writer we trust produce anything at all", not "did
        // anything survive mapping".
        const ignoredSources = new Set<string>();
        let mappedWriterSessions = 0;

        interface CollisionCandidate {
            id: string;
            externalId: string | null;
            durationMinutes: number;
            source: string;
            distanceM: number;
        }
        const byStart = new Map<string, CollisionCandidate>();
        const indexByStart = (type: string, start: string | null, c: CollisionCandidate): void => {
            if (!start) return;
            byStart.set(sameActivityKey(type, start), c);
        };
        for (const a of existing) {
            // The owner's own rows are deliberately NOT in this index (story 299). Manual rows only
            // reached it at all because that story gave them a `metadata.start`, and the
            // consequence would have been severe: an incoming Health Connect session sharing a
            // manual row's type and start instant would take the `isBetter` branch and PATCH the
            // row's source to `health_connect_*`, converting the owner's own log entry into an
            // ingested one. This index exists to arbitrate between Health Connect writers; the
            // owner's own activity is not one of them, it is the record the sync leaves alone.
            //
            // Adopted calendar rows join them for the same reason (story 323). Synthesized ones are
            // excluded for a sharper one: they have no row, so the `isBetter` branch below would
            // fire `PATCH /activities/cal_<eventId>` at nothing and 404 — aborting the entire sync
            // the way story 300's 403 did. `hiit` maps to HC exercise type 36 in both directions,
            // so a TRIB3 class recorded by a writer at the booked instant reaches it.
            if (isUserOwnedActivity(a)) continue;
            indexByStart(a.type, activityStartInstant(a.metadata), {
                id: a.id,
                externalId: a.external_id ?? null,
                durationMinutes: a.duration_minutes ?? 0,
                source: a.source,
                distanceM: a.distance_m ?? 0,
            });
        }

        /**
         * Is the incoming version of a session better than the one already stored? More distance
         * first, then longer duration. The duration tie-break preserves the pre-story-300 behaviour
         * where Health Connect supersedes a partial session with the finished one — without that,
         * refusing to create would strand the fragment forever (e.g. an 18-minute ride where the
         * real one was 81).
         *
         * There is deliberately **no writer preference**, though `CollisionCandidate` carries the
         * source and an earlier version of this comment claimed one. Distance decides, and with
         * Strava mapped alongside Fit that is what makes the right call without naming a favourite:
         * on both runs the two writers recorded together, Strava was the longer track (5114 m vs
         * 5066 m; 6168 m vs 5908 m) and wins on distance alone. A hardcoded ranking would also have
         * to be revisited every time the writer set changes; this does not.
         */
        const isBetter = (incoming: { distanceM: number; durationMinutes: number }, stored: CollisionCandidate): boolean => {
            if (incoming.distanceM !== stored.distanceM) return incoming.distanceM > stored.distanceM;
            return incoming.durationMinutes > stored.durationMinutes;
        };

        for (const bridgeActivity of bridge.activities) {
            if (SOURCE_MAP[bridgeActivity.source]) mappedWriterSessions++;

            const result = mapBridgeActivity(bridgeActivity, timeZone);
            if (result.kind === 'skipped') {
                if (result.reason === 'ignored_source') {
                    summary.skippedIgnoredSource++;
                    ignoredSources.add(bridgeActivity.source);
                } else if (result.reason === 'unknown_type') {
                    summary.skippedUnknownType++;
                    unknownTypes.add(bridgeActivity.exerciseType);
                } else {
                    summary.skippedUnknownSource++;
                    unknownSources.add(bridgeActivity.source);
                }
                continue;
            }

            const existingRow = existingByExternalId.get(result.activity.external_id!);
            if (existingRow) {
                summary.skippedExisting++;
                // Story 259 backfill: rows ingested before the bridge served
                // energy get the real value once a re-sync reports it.
                if (result.activity.calories_burned != null && existingRow.calories_burned == null) {
                    await HealthService.updateActivity(existingRow.id, { calories_burned: result.activity.calories_burned });
                    log.debug('hc-sync: backfilled energy', {
                        external_id: result.activity.external_id,
                        calories_burned: result.activity.calories_burned,
                    });
                    summary.energyBackfilled++;
                }
                continue;
            }

            const newExternalId = result.activity.external_id!;
            const newDuration = result.activity.duration_minutes ?? 0;
            const start = bridgeActivity.start;
            const incoming = {
                source: result.activity.source,
                distanceM: result.distanceMeters,
                durationMinutes: newDuration,
            };

            // Story 300: one row per (type, start instant). Creating a second one is what doubled
            // the history when the phone changed and again when Google Health took over Fit's
            // records — in both cases the HC record id changed, so external_id dedup saw new data.
            const stored = byStart.get(sameActivityKey(result.activity.type, start));
            if (stored) {
                if (isBetter(incoming, stored)) {
                    await HealthService.updateActivity(stored.id, {
                        source: result.activity.source,
                        duration_minutes: newDuration,
                        external_id: newExternalId,
                        metadata: result.activity.metadata,
                        ...(result.activity.calories_burned != null ? { calories_burned: result.activity.calories_burned } : {}),
                    });
                    if (result.distanceMeters > 0) {
                        await HealthService.upsertCardioDetails(stored.id, { distance_m: result.distanceMeters });
                    }
                    log.info('hc-sync: upgraded an existing activity in place', {
                        id: stored.id,
                        start,
                        from: { source: stored.source, durationMinutes: stored.durationMinutes, distanceM: stored.distanceM },
                        to: { source: incoming.source, durationMinutes: newDuration, distanceM: result.distanceMeters },
                    });
                    summary.duplicatesUpgraded++;
                    byStart.set(sameActivityKey(result.activity.type, start), {
                        id: stored.id,
                        externalId: newExternalId,
                        durationMinutes: newDuration,
                        source: incoming.source,
                        distanceM: result.distanceMeters,
                    });
                } else {
                    log.debug('hc-sync: duplicate suppressed', {
                        start,
                        type: result.activity.type,
                        incoming: { source: incoming.source, externalId: newExternalId, distanceM: result.distanceMeters },
                        kept: { id: stored.id, source: stored.source, distanceM: stored.distanceM },
                    });
                    summary.skippedDuplicateStart++;
                }
                continue;
            }

            const created = await HealthService.createActivity(result.activity);
            if (result.distanceMeters > 0) {
                await HealthService.upsertCardioDetails(created.id, { distance_m: result.distanceMeters });
            }
            indexByStart(result.activity.type, start, {
                id: created.id,
                externalId: newExternalId,
                durationMinutes: newDuration,
                source: incoming.source,
                distanceM: result.distanceMeters,
            });

            log.debug('hc-sync: created activity', {
                external_id: result.activity.external_id,
                type: result.activity.type,
                source: result.activity.source,
                date: result.activity.date,
                distance_m: result.distanceMeters,
            });
            summary.created++;
        }

        // Fail loud (story 298). An unrecognised writer is not noise — it is activity ingest
        // silently going to zero, which is what happened when Google Health arrived. Warn with the
        // package name so the fix is a one-line map entry rather than a day of forensics.
        if (unknownSources.size > 0) {
            log.warn('hc-sync: UNKNOWN Health Connect writer(s) — activities dropped', {
                sources: [...unknownSources],
                droppedActivities: summary.skippedUnknownSource,
            });
        }
        if (unknownTypes.size > 0) {
            log.warn('hc-sync: unmapped HC exerciseType(s) — activities dropped', {
                exerciseTypes: [...unknownTypes],
                droppedActivities: summary.skippedUnknownType,
            });
        }

        summary.ignoredSources = [...ignoredSources];
        if (summary.skippedIgnoredSource > 0) {
            log.debug('hc-sync: ignored known writer(s)', {
                sources: summary.ignoredSources,
                skippedActivities: summary.skippedIgnoredSource,
            });
        }

        // Story 303: the cost of trusting one writer. Google Fit producing nothing while a writer
        // we ignore produces sessions is the Google Health migration resuming — the one way
        // Fit-only ingest goes quietly to zero. An empty payload is a quiet day, not a takeover.
        summary.mappedWriterSilent = mappedWriterSessions === 0 && summary.skippedIgnoredSource > 0;
        if (summary.mappedWriterSilent) {
            log.warn('hc-sync: NO sessions from Google Fit — only ignored writer(s) are recording', {
                ignoredSources: summary.ignoredSources,
                theirSessions: summary.skippedIgnoredSource,
            });
        }

        summary.stepDaysUpserted = await this.syncDailySteps(from, today.toString());

        // The write-back runs last, on purpose (story 299). It is the additive half of the story:
        // if publishing fails, the ingest that already ran this sync is still done and stays done.
        // Running it first would let a rejected payload cost the user their activity and step
        // ingest, which is the leg the app actually depends on.
        const push = await this.pushActivities(existing, timeZone, from, today.toString());
        summary.pushedToHealthConnect = push.pushed;
        summary.pushedWithoutStart = push.withoutStart;
        summary.pushRemovedFromHealthConnect = push.removed;
        summary.pushSkippedNoDuration = push.skippedNoDuration;
        summary.pushedStepRecords = push.stepsPushed;
        summary.pushedStepsTotal = push.stepsTotal;
        summary.pushDistanceWithoutSteps = push.distanceWithoutSteps;
        summary.pushStepsExtrapolated = push.stepsExtrapolated;

        return summary;
    }

    /**
     * Publishes Motivation's own activities into Health Connect (story 299).
     *
     * Piggybacks on the sync rather than firing when an activity is logged, which is the story's
     * design decision and the cheap one: the bridge is already awake here (story 301 woke it), a
     * `dataSync` foreground service is already proven to reach Health Connect, and no new lifecycle
     * or background write path has to exist. The cost is latency — a session logged now reaches
     * Health Connect on the next Sync tap, not the instant it is saved.
     *
     * `existing` is reused rather than re-fetched: it is already the server's activities for
     * exactly this window, which is the same set the reconcile has to declare.
     */
    private static async pushActivities(
        existing: ActivityWithDistance[],
        timeZone: string,
        from: string,
        to: string,
    ): Promise<{
        pushed: number;
        withoutStart: number;
        removed: number;
        skippedNoDuration: number;
        stepsPushed: number;
        stepsTotal: number;
        distanceWithoutSteps: number;
        stepsExtrapolated: number;
    }> {
        const plan = buildHealthConnectWrites(existing, timeZone);

        // The declared window bounds what the bridge is allowed to delete, so it must cover every
        // instant being written — including a fallback session walked forward past a clash, and a
        // session whose local date sits at the far edge of the range in the device's zone.
        const windowStart = Temporal.PlainDate.from(from).toZonedDateTime(timeZone).toInstant();
        const windowEnd = Temporal.PlainDate.from(to).add({ days: 2 }).toZonedDateTime(timeZone).toInstant();

        const response = await fetch(`${HC_BRIDGE_URL}/activities`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                windowStart: windowStart.toString(),
                windowEnd: windowEnd.toString(),
                activities: plan.writes,
            }),
        });
        if (!response.ok) {
            const detail = await response.json().catch(() => ({}) as { error?: string; reason?: string });
            if (response.status === 400 || response.status === 403) {
                throw new HcWriteRejectedError(detail.reason ?? 'rejected', detail.error ?? `Bridge POST /activities failed: ${response.status}`);
            }
            throw new Error(`Bridge POST /activities failed: ${response.status} ${detail.error ?? ''}`.trim());
        }
        const result = (await response.json()) as BridgeWriteResponse;
        log.info('hc-sync: published activities to Health Connect', {
            pushed: plan.writes.length,
            withoutStart: plan.placedWithoutStart,
            skippedNoDuration: plan.skippedNoDuration,
            ...result,
        });
        return {
            pushed: result.sessionsWritten,
            withoutStart: plan.placedWithoutStart,
            removed: result.sessionsDeleted,
            skippedNoDuration: plan.skippedNoDuration,
            stepsPushed: result.stepsWritten,
            stepsTotal: result.stepsTotal,
            distanceWithoutSteps: plan.distanceWithoutSteps,
            stepsExtrapolated: plan.stepsExtrapolated,
        };
    }

    /**
     * Steps leg of the sync (story 251): bridge per-day totals are upserted by
     * date, but only days whose total is new or changed are written — an
     * unchanged re-sync must not churn the server (or the offline pending
     * queue) with ~30 no-op writes.
     */
    private static async syncDailySteps(from: string, to: string): Promise<number> {
        const bridge = await this.fetchBridgeDailySteps();
        const existing = await HealthService.getDailySteps(from, to);
        const existingByDate = new Map(existing.map((row) => [row.date, row.steps]));

        let upserted = 0;
        for (const day of bridge.days) {
            if (existingByDate.get(day.date) === day.steps) continue;
            await HealthService.upsertDailySteps(day.date, { steps: day.steps, source: HC_STEPS_SOURCE });
            upserted++;
        }
        log.debug('hc-sync: daily steps', { bridgeDays: bridge.days.length, upserted });
        return upserted;
    }
}
