import stylesText from './hc-sync-panel.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import '../../status-pill/status-dot/status-dot.component.js';
import type { StatusDot } from '../../status-pill/status-dot/status-dot.component.js';
import {
    HealthConnectService,
    HcRateLimitError,
    HcWriteRejectedError,
    HcBridgeUnreachableError,
    HC_BRIDGE_LAUNCH_URL,
    type HcSyncCollision,
    type HcSyncSummary,
} from '../../../services/health-connect.service.js';
import { HealthService } from '../../../services/health.service.js';
import { createHcSyncAppliedEvent } from '../health-events.js';

const styles = cssStyleSheet(stylesText);
const log = createComponentLogger('hc-sync-panel');

/**
 * Story 307 — the whole Health Connect sync interaction as one element, so it
 * can be mounted wherever the user notices they need it: the Status screen's
 * Connected Services block and the day screen's sync dialog both render this.
 *
 * Before this, the sync was split between `status-screen.component.ts` (the
 * service call, the result string, every error branch, the collision delete)
 * and `services-section.component.ts` (the button, the cooldown, the collision
 * cards), stitched together by two status events. A second entry point would
 * have had to duplicate all of it, so it moved here instead — the events are
 * gone and the panel calls the services directly.
 */

/** Health Connect throttles reads; this is how long the button stays shut after a 429. */
const RATE_LIMIT_COOLDOWN_SECONDS = 60;
/** Bridge reachability re-probe, matching the Status screen's old poll. */
const BRIDGE_POLL_MS = 30_000;
/**
 * Device-local on purpose: "when did *this phone* last talk to *its* bridge" is
 * not a synced fact — the bridge exists on one device and nowhere else.
 */
const LAST_SYNC_KEY = 'hc-sync.last-sync-at';

interface ResultLine {
    text: string;
    tone: 'ok' | 'err';
}

/**
 * Shared by every mount, deliberately at module scope. The cooldown especially:
 * it exists to stop us digging deeper into an already-throttled Health Connect
 * read quota, so it cannot be an instance field that dies when you navigate
 * from the day screen to Status — that quota is one quota.
 */
interface HcSyncState {
    syncing: boolean;
    cooldownUntil: number;
    result: ResultLine | null;
    note: ResultLine | null;
    collisions: HcSyncCollision[];
    reachable: boolean | null;
}

const state: HcSyncState = {
    syncing: false,
    cooldownUntil: 0,
    result: null,
    note: null,
    collisions: [],
    reachable: null,
};

const subscribers = new Set<() => void>();

function setState(patch: Partial<HcSyncState>): void {
    Object.assign(state, patch);
    for (const notify of subscribers) notify();
}

/** Wipe the shared state between tests — module scope is the point, so tests must reset it. */
export function resetHcSyncStateForTests(): void {
    setState({ syncing: false, cooldownUntil: 0, result: null, note: null, collisions: [], reachable: null });
}

function readLastSyncAt(): number | null {
    const raw = localStorage.getItem(LAST_SYNC_KEY);
    if (!raw) return null;
    const at = Number(raw);
    return Number.isFinite(at) ? at : null;
}

/** The full result line for a completed sync — the same sentence the Status screen used to build. */
export function formatHcSyncResult(s: HcSyncSummary): ResultLine {
    const skipped = s.skippedExisting + s.skippedUnknownType + s.skippedUnknownSource
        + s.skippedIgnoredSource + s.skippedDuplicateStart;
    // Story 300: duplicates prevented and rows improved in place both change what is
    // stored, so neither should be folded silently into "skipped".
    const deduped = s.skippedDuplicateStart > 0 ? `, ${s.skippedDuplicateStart} duplicate(s) prevented` : '';
    const upgraded = s.duplicatesUpgraded > 0 ? `, ${s.duplicatesUpgraded} improved` : '';
    const backfilled = s.energyBackfilled > 0 ? `, ${s.energyBackfilled} energy backfilled` : '';
    const dupes = s.collisions.length > 0 ? ` ${s.collisions.length} possible duplicate(s) to review below.` : '';
    // Story 298: an unrecognised Health Connect writer means activities are being dropped
    // on the floor. It must reach the user here, not just the log — the last time a writer
    // changed, 94 activities per sync vanished for a day before anyone spotted it.
    const unknown = s.skippedUnknownSource > 0
        ? ` ⚠️ ${s.skippedUnknownSource} activities from an UNRECOGNISED source were dropped — check the hc-sync log.`
        : '';
    // Story 303: ingest trusts Google Fit alone. Fit going quiet while a writer we ignore
    // keeps recording is that bet failing, and it has to be as loud as an unknown writer.
    const silent = s.mappedWriterSilent
        ? ` ⚠️ NO sessions from Google Fit — only ${s.ignoredSources.join(', ')} is recording. Activity ingest has stopped.`
        : '';
    // Story 299: the write-back is invisible everywhere else by design — its records are
    // filtered out of what the bridge serves — so this line is the only place the user
    // learns it ran. `published` is the whole reconciled set, not a delta.
    const removed = s.pushRemovedFromHealthConnect > 0 ? `, ${s.pushRemovedFromHealthConnect} removed` : '';
    const noStart = s.pushedWithoutStart > 0 ? `, ${s.pushedWithoutStart} without a start time` : '';
    const published = ` Published ${s.pushedToHealthConnect} of your own activities to Health Connect${removed}${noStart}.`;
    const result = `Health Connect: ${s.created} new activities, ${s.stepDaysUpserted} step days (${skipped} skipped${backfilled}${deduped}${upgraded}).${published}`;

    return { text: result + dupes + unknown + silent, tone: unknown || silent ? 'err' : 'ok' };
}

/**
 * What to say when a sync throws, and whether to shut the button afterwards.
 * The three typed failures each have a different fix, so they keep their own
 * words; anything else shows what it was and leaves the stack to the log.
 */
export function describeHcSyncFailure(err: unknown): { text: string; cooldownSeconds: number } {
    if (err instanceof HcRateLimitError) {
        // Health Connect throttled reads — back off with a cooldown instead
        // of letting the user hammer sync and dig the quota hole deeper.
        return {
            text: 'Health Connect is rate-limiting reads. Waiting ~60s before you can retry.',
            cooldownSeconds: RATE_LIMIT_COOLDOWN_SECONDS,
        };
    }
    if (err instanceof HcWriteRejectedError) {
        // Story 299. The ingest half of the sync already ran and committed, so this is not
        // "the sync failed" — it is "the write-back was refused", and the two have
        // different fixes. A missing grant is the user's to give; a rejected payload is a
        // bug and gets the bridge's own words, verbatim.
        const text = err.reason === 'write_not_permitted'
            ? 'Activities were read, but publishing yours back was refused: open "Motivation HC Bridge" and allow it to WRITE exercise + distance.'
            : `Activities were read, but the write-back was rejected: ${err.message}`;
        return { text, cooldownSeconds: 0 };
    }
    if (err instanceof HcBridgeUnreachableError) {
        // Story 301: sync already tried to wake it. Reaching here means the wake did not
        // take, so say something actionable instead of surfacing "Failed to fetch".
        return {
            text: 'The HC bridge app did not respond. Open "Motivation HC Bridge" on this phone, '
                + 'check its Health Connect permissions, then sync again.',
            cooldownSeconds: 0,
        };
    }
    const detail = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
    return { text: `Sync FAILED: ${detail}`, cooldownSeconds: 0 };
}

/**
 * The last-synced caption for anywhere outside the panel — the day's Activity
 * tab shows it beside its sync button, which is the screen where "is what I am
 * looking at up to date?" is actually asked.
 */
export function hcLastSyncedLabel(): string {
    return formatLastSynced(readLastSyncAt(), Date.now());
}

/** "Last synced 12 min ago" — the answer to "would syncing even help?". */
export function formatLastSynced(at: number | null, now: number): string {
    if (at === null) return 'Never synced on this device';
    const seconds = Math.max(0, Math.round((now - at) / 1000));
    if (seconds < 60) return 'Last synced just now';
    const minutes = Math.round(seconds / 60);
    if (minutes < 60) return `Last synced ${minutes} min ago`;
    const hours = Math.round(minutes / 60);
    if (hours < 24) return `Last synced ${hours} h ago`;
    const days = Math.round(hours / 24);
    return `Last synced ${days} day${days === 1 ? '' : 's'} ago`;
}

/** Did this sync change anything stored? Only then is a host's re-fetch worth the round trip. */
function syncChangedStoredData(s: HcSyncSummary): boolean {
    return s.created > 0 || s.duplicatesUpgraded > 0 || s.stepDaysUpserted > 0 || s.energyBackfilled > 0;
}

const template = document.createElement('template');
template.innerHTML = `
    <div class="head">
        <status-dot id="dot" title="Health Connect bridge"></status-dot>
        <span class="badge" id="badge"></span>
        <span class="last-sync" id="last-sync"></span>
    </div>
    <div class="actions">
        <button type="button" class="btn btn--primary" id="sync">Sync Health Connect</button>
        <a id="open" class="btn" href="${HC_BRIDGE_LAUNCH_URL}" hidden>Open bridge app</a>
    </div>
    <span class="cooldown" id="cooldown" hidden></span>
    <p class="result" id="result" hidden></p>
    <span class="note" id="note" hidden></span>
    <div class="collisions" id="collisions" hidden></div>
`;

export class HcSyncPanel extends HTMLElement {
    private dot!: StatusDot;
    private badge!: HTMLSpanElement;
    private lastSyncEl!: HTMLSpanElement;
    private syncBtn!: HTMLButtonElement;
    private openLink!: HTMLAnchorElement;
    private cooldownEl!: HTMLSpanElement;
    private resultEl!: HTMLParagraphElement;
    private noteEl!: HTMLSpanElement;
    private collisionsEl!: HTMLDivElement;

    private ticker: ReturnType<typeof setInterval> | null = null;
    private poller: ReturnType<typeof setInterval> | null = null;
    private _active = true;
    private readonly onStateChange = () => this.render();

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));

        this.dot = shadow.getElementById('dot') as StatusDot;
        this.badge = shadow.getElementById('badge') as HTMLSpanElement;
        this.lastSyncEl = shadow.getElementById('last-sync') as HTMLSpanElement;
        this.syncBtn = shadow.getElementById('sync') as HTMLButtonElement;
        this.openLink = shadow.getElementById('open') as HTMLAnchorElement;
        this.cooldownEl = shadow.getElementById('cooldown') as HTMLSpanElement;
        this.resultEl = shadow.getElementById('result') as HTMLParagraphElement;
        this.noteEl = shadow.getElementById('note') as HTMLSpanElement;
        this.collisionsEl = shadow.getElementById('collisions') as HTMLDivElement;

        this.syncBtn.addEventListener('click', () => {
            if (this.syncBtn.disabled) return;
            void this.sync();
        });
    }

    connectedCallback(): void {
        subscribers.add(this.onStateChange);
        this.render();
        if (this._active) this.start();
    }

    disconnectedCallback(): void {
        subscribers.delete(this.onStateChange);
        this.stop();
    }

    /**
     * Whether this mount is on screen. The day screen keeps its panel in the DOM
     * behind a closed dialog — mounted so a sync started before the dialog was
     * closed still reaches the screen with its result, but not probing the
     * bridge on loopback every 30 s for a dialog nobody is looking at.
     */
    set active(value: boolean) {
        if (this._active === value) return;
        this._active = value;
        if (!this.isConnected) return;
        if (value) {
            this.start();
            this.render();
        } else {
            this.stop();
        }
    }

    get active(): boolean {
        return this._active;
    }

    /** Pill-dot color: reachable is green; unreachable is plain gray — a phone-only service being absent (e.g. on desktop) is normal, not an error. */
    static getStatus(reachable: boolean | null) {
        return { color: reachable ? 'green' : 'gray' };
    }

    private start(): void {
        void this.probeBridge();
        if (!this.poller) this.poller = setInterval(() => void this.probeBridge(), BRIDGE_POLL_MS);
        this.ensureTicker();
    }

    private stop(): void {
        if (this.poller) clearInterval(this.poller);
        this.poller = null;
        if (this.ticker) clearInterval(this.ticker);
        this.ticker = null;
    }

    private async probeBridge(): Promise<void> {
        const reachable = await HealthConnectService.pingBridge();
        setState({ reachable });
    }

    private async sync(): Promise<void> {
        if (state.syncing || cooldownRemainingMs() > 0) return;
        setState({ syncing: true, note: null });
        try {
            const summary = await HealthConnectService.sync();
            localStorage.setItem(LAST_SYNC_KEY, String(Date.now()));
            setState({ result: formatHcSyncResult(summary), collisions: summary.collisions });
            if (syncChangedStoredData(summary)) {
                this.dispatchEvent(createHcSyncAppliedEvent({ summary }));
            }
        } catch (err) {
            log.error('HealthConnectService.sync failed:', err);
            const failure = describeHcSyncFailure(err);
            setState({ result: { text: failure.text, tone: 'err' } });
            if (failure.cooldownSeconds > 0) {
                setState({ cooldownUntil: Date.now() + failure.cooldownSeconds * 1000 });
                this.ensureTicker();
            }
        } finally {
            setState({ syncing: false });
            await this.probeBridge();
        }
    }

    /** Re-render once a second while a cooldown is counting down, then stop. */
    private ensureTicker(): void {
        if (this.ticker || cooldownRemainingMs() <= 0) return;
        this.ticker = setInterval(() => {
            if (cooldownRemainingMs() <= 0) {
                clearInterval(this.ticker!);
                this.ticker = null;
            }
            this.render();
        }, 1000);
    }

    private async deleteCollision(activityId: string, collision: HcSyncCollision): Promise<void> {
        try {
            await HealthService.deleteActivity(activityId);
            setState({
                collisions: state.collisions.filter((c) => c !== collision),
                note: { text: 'Duplicate activity deleted.', tone: 'ok' },
            });
            this.dispatchEvent(createHcSyncAppliedEvent({ summary: null }));
        } catch (err) {
            log.error(`deleteActivity(${activityId}) failed:`, err);
            const detail = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
            setState({ note: { text: `Delete FAILED: ${detail}`, tone: 'err' } });
        }
    }

    private render(): void {
        const { reachable } = state;

        this.dot.setAttribute('color', reachable === null ? 'gray' : reachable ? 'green' : 'red');
        this.badge.textContent = reachable === null ? 'Checking…' : reachable ? 'Reachable' : 'Unreachable';
        this.badge.className = `badge ${reachable ? 'badge--reachable' : ''}`;
        this.openLink.hidden = reachable !== false;

        this.lastSyncEl.textContent = formatLastSynced(readLastSyncAt(), Date.now());

        const cooldownMs = cooldownRemainingMs();
        // Disabled while a sync is in flight or cooling down — NOT re-enabled by a
        // status re-render mid-sync (the old bug that allowed rapid re-taps).
        this.syncBtn.disabled = state.syncing || cooldownMs > 0;
        this.syncBtn.textContent = state.syncing ? 'Syncing…' : 'Sync Health Connect';

        this.cooldownEl.hidden = cooldownMs <= 0;
        if (cooldownMs > 0) {
            this.cooldownEl.textContent = `Health Connect rate-limited — retry in ${Math.ceil(cooldownMs / 1000)}s`;
        }

        this.resultEl.hidden = state.result === null;
        this.resultEl.textContent = state.result?.text ?? '';
        this.resultEl.className = `result${state.result?.tone === 'err' ? ' result--err' : ''}`;

        this.noteEl.hidden = state.note === null;
        this.noteEl.textContent = state.note?.text ?? '';
        this.noteEl.className = `note${state.note?.tone === 'err' ? ' note--err' : ''}`;

        this.renderCollisions();
    }

    /**
     * Same-start duplicates a sync flagged (story 300). Each renders a "delete
     * which copy?" prompt, and the delete happens right here — wherever the
     * panel is mounted, the decision is available.
     */
    private renderCollisions(): void {
        // Keyed on the flagged rows themselves: a cooldown ticks once a second,
        // and rebuilding these cards under the user's finger each tick would
        // steal the tap that resolves them.
        const ids = state.collisions.map((c) => c.newId).join(',');
        if (this.collisionsEl.dataset.renderedIds === ids) return;

        this.collisionsEl.dataset.renderedIds = ids;
        this.collisionsEl.replaceChildren();
        this.collisionsEl.hidden = state.collisions.length === 0;
        for (const collision of state.collisions) {
            this.collisionsEl.appendChild(this.buildCollisionCard(collision));
        }
    }

    private buildCollisionCard(c: HcSyncCollision): HTMLDivElement {
        const card = document.createElement('div');
        card.className = 'collision';
        const label = c.type.charAt(0).toUpperCase() + c.type.slice(1);
        const at = new Date(c.start).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

        const p = document.createElement('p');
        p.textContent = `Possible duplicate: a new ${label} (${c.newDurationMinutes} min) and an existing one `
            + `(${c.existingDurationMinutes} min) both start at ${at}. Health Connect likely re-recorded it — delete one?`;

        const row = document.createElement('div');
        row.className = 'row';
        row.appendChild(this.deleteButton(`Delete previous (${c.existingDurationMinutes}m)`, c.existingId, c));
        row.appendChild(this.deleteButton(`Delete new (${c.newDurationMinutes}m)`, c.newId, c));
        const keep = document.createElement('button');
        keep.type = 'button';
        keep.textContent = 'Keep both';
        keep.addEventListener('click', () => this.dismissCollision(c));
        row.appendChild(keep);

        card.append(p, row);
        return card;
    }

    private deleteButton(text: string, activityId: string, collision: HcSyncCollision): HTMLButtonElement {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = text;
        btn.addEventListener('click', () => void this.deleteCollision(activityId, collision));
        return btn;
    }

    private dismissCollision(collision: HcSyncCollision): void {
        setState({ collisions: state.collisions.filter((c) => c !== collision) });
    }
}

function cooldownRemainingMs(): number {
    return state.cooldownUntil - Date.now();
}

if (!customElements.get('hc-sync-panel')) {
    customElements.define('hc-sync-panel', HcSyncPanel);
}
